mapper.select:
SELECT br.id, br.tenant_id, br.result_id, br.host_id, br.rule_id, br.remediation_type, br.old_value, br.new_value,
       br.backup_data, br.execute_script, br.operator, br.message, br.status, br.start_time, br.end_time, br.create_time
FROM baseline_remediation br
LEFT JOIN baseline_result r ON r.id = br.result_id AND r.tenant_id = #{tenantId}
WHERE br.host_id = #{hostId}
  AND br.tenant_id = #{tenantId}
  AND br.rule_id = #{ruleId}
  AND COALESCE(r.check_key, '') = COALESCE(#{checkKey}, '')
  AND br.status = 'SUCCESS'
ORDER BY br.end_time DESC, br.id DESC
LIMIT 1

SELECT br.id, br.tenant_id, br.result_id, br.host_id, br.rule_id, br.remediation_type, br.old_value, br.new_value,
       br.backup_data, br.execute_script, br.operator, br.message, br.status, br.start_time, br.end_time, br.create_time
FROM baseline_remediation br
LEFT JOIN baseline_result r ON r.id = br.result_id AND r.tenant_id = #{tenantId}
WHERE br.host_id = #{hostId}
  AND br.tenant_id = #{tenantId}
  AND br.rule_id = #{ruleId}
  AND COALESCE(r.check_key, '') = COALESCE(#{checkKey}, '')
ORDER BY br.create_time DESC, br.id DESC
